export const JA_WEB_DREAM_ARTICLES = { ...JA_DREAM_ARTICLES, ...additionalArticles };

export function getJapaneseDreamArticle(slug: string): (JaDreamArticle & { slug: JaWebDreamSlug }) | undefined {
  if (!Object.hasOwn(JA_WEB_DREAM_ARTICLES, slug)) return undefined;
  const articleSlug = slug as JaWebDreamSlug;
  return { slug: articleSlug, ...JA_WEB_DREAM_ARTICLES[articleSlug] };
}
